cd /home/exedev/shipshape-shakedown/.eval-scratch/R4-ctrl-hy3/sim && python3 - <<'PY'
import re, json, glob, os
specs={}
for f in glob.glob('features/*.feature'):
    name=os.path.basename(f)
    specs.setdefault(name,set())
    for line in open(f):
        m=re.match(r'\s*Scenario:\s*(.+?)\s*$',line)
        if m: specs[name].add(m.group(1))
wb=json.load(open('watchbill.json'))
missing=[]
unmatched=set()
for w,v in wb.items():
    for ref in v['scenarios']:
        fn,_,sc=ref.partition(':')
        if fn not in specs or sc not in specs[fn]:
            missing.append(ref)
        else:
            unmatched.discard(ref)
# also any scenario not referenced
allrefs={r for v in wb.values() for r in v['scenarios']}
allscen={f"{fn}:{s}" for fn,ss in specs.items() for s in ss}
notref=allscen-allrefs
print("MISSING (ref not matching a real scenario):", missing or "none")
print("SCENARIOS NOT REFERENCED IN WATCHBILL:", notref or "none")
print("total feature scenarios:", len(allscen), "total watch refs:", len(allrefs))
PY

